using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Payments.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Payments.Commands.PostPayment;public sealed class PostPaymentCommandHandler(IPaymentRepository repository,IUserRepository users,IApplicationDbContext db):IRequestHandler<PostPaymentCommand,Result<PaymentDto>>{public async Task<Result<PaymentDto>>Handle(PostPaymentCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<PaymentDto>(PaymentErrors.NotFound);if(e.Status!="Draft")return Result.Failure<PaymentDto>(PaymentErrors.NotDraft);if(!await users.ExistsByIdAsync(request.PostedByUserId,cancellationToken))return Result.Failure<PaymentDto>(new Error("Payments.UserNotFound","The user was not found.",ErrorType.NotFound));e.Post(request.PostedByUserId,request.PostedAt);await db.SaveChangesAsync(cancellationToken);return Result.Success(PaymentDto.FromEntity(e));}}
